-- P22 The Hidden Layer - Stage 4
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Bay 1 Reinspection - Facade Exhibit","dataPayload":"REOPENED EXHIBIT, P01 facade photograph: the carved band is eight marks deep, not seven. The eighth mark, at the far right, is a CROSS laid over an aborted stroke - the cut was started, abandoned, and crossed out in the same stone. At intake it was filed as damage. Bay 1''s own specimen plate repeats the same cross shape beside every job the shop left unfinished.","visualType":"observation","whatTheySee":"The eighth lintel mark is a cross cut over an aborted letter, filed at intake as damage.","taskPrompt":"Record the shape of the eighth mark and how it sits in the stone.","intermediateOutput":"The eighth mark is a cross laid over an aborted cut - a correction, not a letter."},"analyst":{"role":"ANALYST","screenTitle":"Manifold Notation Key","dataPayload":"NOTATION KEY, Bay 1 manifold ledger: every quantity the programme failed to solve was entered in the ledger by its mark, pending measurement. The key defines three marks: a RING means a value on file; a CARET means a value estimated; a CROSS means a value never solved - the unknown the whole manifold was written around. The ledger''s current sheet carries one live cross entry, unmeasured since the night of the seal.","visualType":"document-forensics","whatTheySee":"A notation key defining ring, caret and cross, and a ledger sheet with one live cross entry.","taskPrompt":"Match the eighth facade mark against the key: what does the programme record when a quantity was never solved?","intermediateOutput":"The cross is the ledger mark for a quantity never solved."},"operator":{"role":"OPERATOR","screenTitle":"Bay 1 Ledger - Unknown Field","dataPayload":"LEDGER FIELD, open since the seal: \"UNKNOWN OF THE MANIFOLD, ENTERED AS: [_]\". The bay will accept the single character the notation key gives the unsolved quantity. The intake card filed the eighth facade mark as damage; the ledger files the same shape as the quantity the case was solved around. Submit the character.","visualType":"meta","whatTheySee":"A ledger field awaiting the single character that marks the unsolved quantity.","taskPrompt":"Enter the character the programme used for the unknown.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The reopened facade exhibit, the notation key, and the ledger field open since the seal.","operatorTaskDescription":"The Observer reopens the P01 exhibit and records the eighth mark; the Analyst matches it against the notation key; the Operator enters the character.","requiredDiscoveries":{"observerDiscovery":"Finds the eighth mark is a cross over an aborted cut, filed as damage at intake.","analystDiscovery":"Reads the key: the cross marks the quantity never solved."}},"coordinationChain":{"observerProduces":"Observer reports the eighth facade mark as a correction cut over an aborted stroke.","analystTransforms":"Analyst matches the shape to the key: the mark of the never-solved quantity.","operatorExecutes":"Operator enters the character the key names, unlocking P23."},"hints":["The eighth mark was filed as damage at intake, but the bay ledger files the same shape with a meaning.","The notation key defines three marks: ring for a value on file, caret for an estimate, cross for a value never solved.","The ledger asks for the single character that stands for that unsolved quantity."],"narrativeObjective":"Reopen the P01 facade exhibit and establish what the eighth mark actually records.","roleDependencyLevel":"D4"}',
  answer_metadata = '{"acceptedAnswer":"X","validationMethod":"exact","fullSolution":"The eighth lintel mark is a correction cut over an aborted letter, and the bay notation key defines that same cross as the entry for a quantity never solved. The character the programme entered for the unknown of the manifold is X."}',
  metadata = '{"type":"LOGIC","difficulty":4.5,"time":"12m","storyReveal":"The eighth mark on the lintel was filed as damage by everyone who walked past it. It is the unknown the whole manifold was solved around, and Stage 1 handed it over at the front door.","locationClue":{"format":"Research-Note","clueText":"LINA''S NOTE: \"The robotics lab has autonomous arms in darkness. Find Bay 1.\"","solution":"Engineering Block Robotics Bay 1","nextPhysicalLocation":"[ENGINEERING BLOCK] - Robotics Bay 1","nextQrNode":"QR-NODE-23","explanation":"Points to Robotics Bay 1."},"evidenceUnlocked":{"id":"EVID-P22","category":"Lab Note","title":"Lab Notebook Fragment #51","state":"RECOVERED","timestamp":"Stage 4","source":"Robotics Bay 1 terminal","content":"They would never look back at it. Human psychology makes us discard a mark once a door opens. But the programme re-weaves old threads: the cross above the entrance was never a room and never damage. It is the unknown the entire manifold was written for."},"whyTeamworkMatters":"Only the reopened exhibit shows the mark is a correction; only the notation key gives that shape a meaning; only the ledger accepts the character.","feeds":"M03"}'
WHERE code = 'P22';

-- P23 The Reinterpretation - Stage 4
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Antenna Deck - Two Reports","dataPayload":"TWO REPORTS ON ONE EVENING. REPORT A, police bulletin (external, civil time): \"Subject departed the building at 17:30. Search bus stops.\" REPORT B, house surveillance register (house time): \"East door activity 21:47. Lobby clock stopped at the same minute. Building sealed.\" Both records on this deck are duty-office copies; each carries the same filing line stamped along its top edge: DUTY LIAISON: DR. A. VALE. The two reports cannot both be read as written: they put the same subject inside and outside at once.","visualType":"observation","whatTheySee":"A civil-time bulletin claiming a 17:30 departure, and a house register logging east-door activity at 21:47; both stamped with the same duty-liaison filing line.","taskPrompt":"Record both readings of the evening, and what each one implies about where the subject was.","intermediateOutput":"The bulletin has her leaving at 17:30; the register has her at the east door at 21:47."},"analyst":{"role":"ANALYST","screenTitle":"Transcription Card - House Offset","dataPayload":"TRANSCRIPTION CARD: external documents in this case were typed under the standing transcription instruction - add FOUR HOURS AND SEVENTEEN MINUTES to any civil time to read house time. The same instruction is printed on every bulletin copies file in this case. Applying it: the bulletin''s departure time becomes 21:47 house time - the exact minute the lobby clock stopped and the seal came down. The bulletin never described a departure. It described the seal.","visualType":"document-forensics","whatTheySee":"A transcription card fixing the offset between civil and house time at four hours and seventeen minutes.","taskPrompt":"Apply the transcription offset to the bulletin and decide whether the two reports still conflict.","intermediateOutput":"Under the offset the departure and the seal are the same minute: she never left."},"operator":{"role":"OPERATOR","screenTitle":"Deck Plate - House Directive","dataPayload":"HOUSE DIRECTIVE, standing order plate on the deck: \"WHEN AN EXTERNAL REPORT CONFLICTS WITH A HOUSE RECORD, DO NOT CHOOSE BETWEEN THEM. APPLY THE DIRECTIVE.\" The deck lexicon card: the directive is ELEVEN LETTERS, opens with RE-, closes with -PRET, and names the act of reading prior evidence inside the frame it was written in. The directive field awaits the word.","visualType":"meta","whatTheySee":"A standing-order plate and a lexicon card describing an eleven-letter directive.","taskPrompt":"Enter the directive the deck requires.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The two conflicting reports, the transcription card, and the standing directive plate.","operatorTaskDescription":"The Observer records both reports; the Analyst applies the house offset and dissolves the contradiction; the Operator enters the directive.","requiredDiscoveries":{"observerDiscovery":"Records the bulletin (17:30 civil) and the register (21:47 house) as a direct conflict.","analystDiscovery":"Applies the four-hours-seventeen offset: the departure time lands on the seal minute; she never left."}},"coordinationChain":{"observerProduces":"Observer reports the two irreconcilable accounts of the departure.","analystTransforms":"Analyst applies the transcription offset and shows the reports describe one minute.","operatorExecutes":"Operator enters the eleven-letter directive, unlocking P24."},"hints":["The bulletin and the house record do not have to contradict each other.","The deck transcription card maps civil time to house time: add four hours and seventeen minutes. Apply it to the departure time.","The directive names the act of reading prior evidence inside the frame it was written in: eleven letters, opening RE- and closing -PRET."],"narrativeObjective":"Resolve the departure contradiction by the archive''s own transcription rule, then name the standing directive.","roleDependencyLevel":"D4"}',
  answer_metadata = '{"acceptedAnswer":"REINTERPRET","validationMethod":"exact","fullSolution":"The transcription card fixes the house offset at four hours and seventeen minutes, which turns the bulletin''s 17:30 departure into 21:47 house time - the seal minute itself; the subject never left. The eleven-letter standing directive for reading prior evidence inside its own frame is REINTERPRET."}',
  metadata = '{"type":"DEDUCTION","difficulty":4.5,"time":"12m","storyReveal":"The departure was an artefact of two clocks, not a lie. The bulletin and the register describe the same minute in two conventions - and at that minute the building was being sealed around her.","locationClue":{"format":"Poetic","clueText":"LINA''S NOTE: \"Ascend the external spiral staircase to the communications antenna deck.\"","solution":"Engineering Communications Antenna Deck","nextPhysicalLocation":"[ENGINEERING BLOCK] - Antenna Deck","nextQrNode":"QR-NODE-24","explanation":"Points to the antenna deck."},"evidenceUnlocked":{"id":"EVID-P23","category":"Audio","title":"Dictaphone Memo REC-16: Two Clocks","state":"RECOVERED","timestamp":"Stage 4","source":"Robotic arm control cabinet","content":"The bulletin says I left at half past five in the afternoon. Candidate 01 will search bus stops if they trust it. Read the house records inside the frame the bulletin was written in, and the departure dissolves: I am in the communications array, and the seal is what they saw."},"whyTeamworkMatters":"Only the deck holds both reports; only the transcription card fixes the offset between them; only the directive plate names the operation the case runs on.","feeds":"P22"}'
WHERE code = 'P23';

-- P23b The Path Lock - Stage 4
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Vent Hatch - Grating Plan","dataPayload":"MAINTENANCE VENT HATCH: a 6x6 grating plan, entry corner top-left (S), exit corner bottom-right (E). One route is inked in dashes across the grating; walls block every other square. The hatch plate carries two stamped numbers: 14 and 41. The 41 stamp has been struck through and restamped; the 14 stamp is fresh. THE INKED ROUTE: S, right one; down one; right four; down one; left four; down one; right one; down one; left one; down one; right three; up one; right one; down one; E.","visualType":"observation","whatTheySee":"A 6x6 grating with one dashed route from S to E, and two stamps on the plate, 14 and 41, one struck through.","taskPrompt":"Trace the inked route from S to E in travel order and record it as written.","intermediateOutput":"One dashed route, S to E, with turns; two stamped numbers, one struck."},"analyst":{"role":"ANALYST","screenTitle":"Route Register - Counting Convention","dataPayload":"ROUTE REGISTER: \"A route number counts the STRAIGHT RUNS of the inked line: each run lasts from one turn to the next. Cells crossed are not the unit; sums and reversals are not the unit. Routes are logged from entry to exit.\" The register also warns that restamped plates in this block keep the aborted first stamp beside the live one. The struck stamp on this hatch does not match any count of the inked line.","visualType":"document-forensics","whatTheySee":"A register defining the route number as the count of straight runs, entry to exit.","taskPrompt":"Apply the register convention to the inked route and decide which stamp is the live route number.","intermediateOutput":"The convention counts straight runs in travel order; the struck stamp matches nothing."},"operator":{"role":"OPERATOR","screenTitle":"Vent Control - Route Field","dataPayload":"VENT CONTROL: route field awaiting the live route number. The plate offers two candidates; the register decides which kind of number this field takes. Enter the count of straight runs on the inked line, from entry to exit.","visualType":"meta","whatTheySee":"A two-digit route field beside the plate''s two stamps.","taskPrompt":"Submit the live route number.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The grating plan, the two stamps, and the register convention.","operatorTaskDescription":"The Observer traces the inked route; the Analyst applies the counting convention and rejects the struck stamp; the Operator submits the live route number.","requiredDiscoveries":{"observerDiscovery":"Records the inked route and its turns from S to E, and both plate stamps.","analystDiscovery":"Applies the straight-run convention: the route is fourteen runs; 41 matches no count of this line."}},"coordinationChain":{"observerProduces":"Observer reports the inked route in travel order and both stamps.","analystTransforms":"Analyst counts straight runs under the register convention and rejects the struck stamp.","operatorExecutes":"Operator submits the live route number, unlocking P24."},"hints":["The plate carries two numbers; the register decides which kind of number a route stamp is.","A route number counts straight runs: every time the inked line turns, one run ends. The cells it crosses are not the unit.","Count the runs in travel order, entry corner to exit corner. One of the two stamps is that count."],"narrativeObjective":"Determine the live vent route number under the house counting convention.","roleDependencyLevel":"D3"}',
  answer_metadata = '{"acceptedAnswer":"14","validationMethod":"exact","fullSolution":"The register counts a route by its straight runs in travel order, not by cells crossed. The inked line from S to E turns thirteen times, giving fourteen runs; the live stamp 14 is that count, and the struck 41 matches no count of this route."}',
  metadata = '{"type":"LOGIC","difficulty":4,"time":"8m","storyReveal":"The vent route was never a maze. It was a counting convention: the house logs its paths by straight runs, and the plate kept the aborted stamp of whoever counted cells instead.","locationClue":{"format":"Research-Note","clueText":"LINA''S NOTE: \"The antenna deck above has data streams flooding the terminal.\"","solution":"Communications Antenna Deck","nextPhysicalLocation":"[ENGINEERING BLOCK] - Communications Antenna Deck","nextQrNode":"QR-NODE-25","explanation":"Points to the antenna deck."},"evidenceUnlocked":{"id":"EVID-P23b","category":"Blueprint","title":"Maintenance Vent Layout","state":"RECOVERED","timestamp":"Stage 4","source":"Robotics Bay 1 vent control","content":"A 6x6 grating plan with one inked route from entry to exit. The register line reads: route numbers count straight runs, logged entry to exit. The plate carries a live stamp and a struck-through earlier stamp."},"whyTeamworkMatters":"Only the plan shows the route and its turns; only the register defines what a route number counts; only the control field takes the number.","feeds":"P23"}'
WHERE code = 'P23b';

-- P24 The Cross-Reference - Stage 4
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Waveguide Junction - Three Seals","dataPayload":"JUNCTION CABINET: three departmental seals are bolted across the cabinet face - RECORDS, ENGINEERING, PERSONNEL - from three different offices of the institute. All three seals carry the SAME case-file address: BINDER THIRTY-FOUR, SHELF TWO, FILE FIVE. The cabinet''s pull register shows the binder was drawn by Records on one day, Engineering the next, Personnel the day after.","visualType":"observation","whatTheySee":"Three office seals sharing one case-file address, and a pull register with three consecutive days.","taskPrompt":"Record the address on each seal and the pull dates in the register.","intermediateOutput":"Three seals, one shared address; three pulls on consecutive days."},"analyst":{"role":"ANALYST","screenTitle":"Pull Register - Coincidence Test","dataPayload":"TEST: a coincidence would leave independent references - different binders, scattered dates, no shared chain. Here the three offices cite one address and their pulls run in sequence, each office drawing the file the previous office returned. The evidence standard for ONE PROCEEDING citing one file across three offices is met. This is the paper trail of a single programme, and the house has a name for exactly this condition.","visualType":"document-forensics","whatTheySee":"A test that separates coincidence from one proceeding, applied to the three pulls.","taskPrompt":"Decide from the register whether the shared address is coincidence, a joint project, or one programme.","intermediateOutput":"One file, pulled in sequence by three offices: one programme."},"operator":{"role":"OPERATOR","screenTitle":"Condition Field - Mark Name","dataPayload":"CONDITION FIELD: the shared reference evidences a condition the house carved its second condition-mark for in Stage 3 - the condition of a subject LINKED into the programme lattice. That mark''s name was filed with your reading-room exhibits: TEN LETTERS, meaning the link between entities. The field will accept nothing else.","visualType":"meta","whatTheySee":"A condition field that names the second condition-mark and its letter count.","taskPrompt":"Enter the name of the condition all three seals evidence.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The three seals, the shared address, and the pull register sequence.","operatorTaskDescription":"The Observer records the seals and pulls; the Analyst tests coincidence against one proceeding; the Operator files the condition name recovered in Stage 3.","requiredDiscoveries":{"observerDiscovery":"All three seals carry one case-file address; the pulls run in sequence over three days.","analystDiscovery":"Establishes one programme from the sequential pulls, not coincidence."}},"coordinationChain":{"observerProduces":"Observer reports three seals on one address and three consecutive pulls.","analystTransforms":"Analyst proves one file across three offices: a single programme.","operatorExecutes":"Operator enters the ten-letter condition name from the Stage 3 exhibits, unlocking P25."},"hints":["Three offices pulled the same binder on three consecutive days; each drew the file the last returned.","The second condition-mark, recovered in Stage 3, names the condition that a shared file reference evidences: a subject linked into the lattice.","Its name is ten letters and means the link between entities; it is already filed with your Stage 3 exhibits."],"narrativeObjective":"Establish that the three departmental seals document one programme, and name the condition they evidence.","roleDependencyLevel":"D4"}',
  answer_metadata = '{"acceptedAnswer":"CONNECTION","validationMethod":"exact","fullSolution":"All three seals carry one case-file address and the pulls run in sequence, each office drawing what the last returned: one file across three offices is one programme, not a coincidence. The second condition-mark names that condition, and its ten-letter name is CONNECTION."}',
  metadata = '{"type":"CROSS_REFERENCE","difficulty":4.5,"time":"11m","storyReveal":"Three departments, one binder, three consecutive pull days. The shared reference was filed to read as three coincidences; it is the paper trail of a single programme.","locationClue":{"format":"Research-Note","clueText":"LINA''S NOTE: \"Descend to the server room cooling corridor. Data streams flood the terminal.\"","solution":"Engineering Server Room Cooling Corridor","nextPhysicalLocation":"[ENGINEERING BLOCK] - Cooling Corridor","nextQrNode":"QR-NODE-25","explanation":"Points to the cooling corridor."},"evidenceUnlocked":{"id":"EVID-P24","category":"Lab Note","title":"Lab Notebook Fragment #58","state":"RECOVERED","timestamp":"Stage 4","source":"Antenna waveguide junction","content":"Three offices pulled the same binder in three days. Whoever filed that address wanted it to read as three coincidences. It is one file. It was always one file."},"whyTeamworkMatters":"Only the cabinet shows the three seals on one address; only the pull register proves the pulls ran in sequence; only the Stage 3 exhibits hold the name of the condition.","feeds":"P23"}'
WHERE code = 'P24';

-- P24b The False Witness - Stage 4
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Interrogation Room - Recording Playback","dataPayload":"AUDIO TRANSCRIPT, REC-19, four statements taken in the antenna deck interrogation room on the night of the seal: DR. ADRIAN: I reviewed the east laboratory security footage at 04:17 and confirmed DR. VEYR was present. DR. VEYR: I was in the east laboratory when the containment alarm sounded at 04:17. MARA SELIM: I saw DR. VEYR in the west corridor at 04:20. NOOR RAHAL: The east laboratory camera array was powered down for maintenance beginning at 04:15. ACCESS LOG: badge of DR. VEYR swiped at the east laboratory door at 04:17, west corridor at 04:20.","visualType":"audio","whatTheySee":"A four-statement transcript and a badge access log; each statement is pinned to a minute of that night.","taskPrompt":"Record all four statements and the badge log exactly as taken.","intermediateOutput":"Four statements recorded; three describe where someone was, one describes having watched the record of where someone was."},"analyst":{"role":"ANALYST","screenTitle":"Timeline Integrity Check - Camera Array","dataPayload":"CAMERA MAINTENANCE LOG: east laboratory camera array, power-down at 04:15:03, physical disconnection confirmed; no recording exists from that array after that minute on any recovered material. A statement that a person WATCHED footage from a minute after the array went dark cannot be true as recorded - there was nothing to watch. Statements of presence can be tested against the badge log; a statement of having viewed footage can only be tested against this maintenance record.","visualType":"document-forensics","whatTheySee":"A maintenance log fixing the physical end of the east-lab recording at 04:15:03.","taskPrompt":"Test each statement against the record that could contradict it, and identify which statement fails.","intermediateOutput":"Three statements are corroborated or unremarkable; one claims to have viewed footage that cannot exist."},"operator":{"role":"OPERATOR","screenTitle":"Contradiction Terminal - Witness Field","dataPayload":"CONTRADICTION TERMINAL: the interrogation analysis flags exactly one statement as physically impossible as recorded. The field awaits the SURNAME of the witness who made it. The transcript names the witnesses by given name only; the department files its liaison''s surname on the duty-office filing line carried by every record of this department - including the two records recovered at the antenna deck.","visualType":"meta","whatTheySee":"A four-letter surname field and a flag reading: one statement impossible as recorded.","taskPrompt":"Submit the surname of the witness whose statement the maintenance log contradicts.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The interrogation flag, the camera maintenance timestamp, and the duty-office filing line carried by the deck records.","operatorTaskDescription":"The Observer takes the four statements; the Analyst tests them against the camera maintenance log; the Operator names the witness whose statement fails, using the surname the department files its liaison under.","requiredDiscoveries":{"observerDiscovery":"Records four statements and notes that one of them describes viewing camera footage rather than being somewhere.","analystDiscovery":"Finds the array went dark at 04:15:03, which makes one statement impossible as recorded."}},"coordinationChain":{"observerProduces":"Observer reports all four statements and the badge log.","analystTransforms":"Analyst identifies the impossible statement from the camera maintenance log.","operatorExecutes":"Operator submits the surname of that witness, unlocking P25."},"hints":["Four witnesses spoke; only one of them claims to have watched a recording rather than to have been somewhere.","The camera maintenance log fixes the exact minute the east-lab array stopped recording, and that minute falls before the footage the witness claims to have watched.","The transcript gives the witnesses by given name only; the duty-office filing line on the antenna-deck records carries the liaison''s surname."],"narrativeObjective":"Identify the witness whose statement the camera maintenance log makes physically impossible.","roleDependencyLevel":"D3"}',
  answer_metadata = '{"acceptedAnswer":"VALE","validationMethod":"exact","fullSolution":"Dr. Adrian claims to have reviewed east-laboratory footage at 04:17, but the camera maintenance log records the array powered down and physically disconnected at 04:15:03 - nothing remained to review. The other three statements are corroborated by the badge log or by the log itself. The duty-office filing line on the antenna-deck records names the department liaison whose surname is VALE."}',
  metadata = '{"type":"NARRATIVE_INVESTIGATION","difficulty":4,"time":"7m","storyReveal":"The interrogation was staged around a witness who claimed to have watched footage that no longer existed. The contradiction is not an error in the transcript - it is the seam where the department''s account of that night was written rather than recorded.","locationClue":{"format":"Research-Note","clueText":"LINA''S NOTE: \"Descend to the server room cooling corridor. Data streams flood the terminal.\"","solution":"Server Room Cooling Corridor","nextPhysicalLocation":"[ENGINEERING BLOCK] - Cooling Corridor","nextQrNode":"QR-NODE-26","explanation":"Points to the cooling corridor."},"evidenceUnlocked":{"id":"EVID-P24b","category":"Audio","title":"Interrogation Recording REC-19","state":"RECOVERED","timestamp":"Stage 4","source":"Antenna Deck interrogation room","content":"The witness who claimed to have reviewed east-laboratory footage at 04:17 is contradicted by the camera maintenance log: the array was powered down at 04:15:03. One statement in the record was written, not remembered."},"whyTeamworkMatters":"Only the transcript carries the statements; only the maintenance log can contradict one of them; only the deck records carry the surname the terminal requires.","feeds":"P24"}'
WHERE code = 'P24b';

-- P25 The Noise Gate - Stage 4
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Data Flood Console - Bank A","dataPayload":"DATA FLOOD CONSOLE, BANK A: a wall of scrolling noise - hex rows, dead bytes, machine chatter - forty rows deep and unreadable at speed. Bolted beside the wall, the CONSOLE MANUAL lies open and numbered the same way the bank prints its rows. Sample rows: 01 RECEIVES THE STREAM AND HOLDS IT IN THE BANK. 02 EMITS A STAMPED CLOCK FOR THE BANK. 16 COUNTS THE ROWS THAT FAILED THE LAST RUN. 17 KEEPS ONLY THE LINES THAT PASS THE PIVOT TEST AND DISCARDS THE REST. CLASS F******. 18 MARKS THE RUN CLOSED AND SEALS THE BANK. The manual is long; the wall never stops.","visualType":"observation","whatTheySee":"An unreadable forty-row noise wall beside a numbered console manual of operation definitions.","taskPrompt":"Record the manual page - its row numbers, jobs and class masks - exactly as printed. Do not yet decide which row matters.","intermediateOutput":"Forty manual rows recorded; row 17 prints a job and a six-letter class mask."},"analyst":{"role":"ANALYST","screenTitle":"Pivot Card - Manual Row Selection","dataPayload":"PIVOT CARD, carried from Stage 2: the stack reference desk card stamped PIVOT 17, cross-stamped to subject heading 17. The console manual is numbered the way the subject register was: the pivot selects one row. Row 17 defines the gate operation this console runs - keep only the lines that pass the pivot test, discard the rest - and its class mask prints F******: six letters, first letter F. The row gives the job and the shape of the name; it never prints the name.","visualType":"document-forensics","whatTheySee":"The Stage 2 pivot card selecting manual row 17, whose definition carries a six-letter mask beginning F.","taskPrompt":"Apply the pivot to the manual and decide what the gate operation is called, from its job and its mask.","intermediateOutput":"Row 17 is the gate operation: a six-letter F-word for keeping only what passes the test."},"operator":{"role":"OPERATOR","screenTitle":"Stream Gate - Operation Field","dataPayload":"STREAM GATE, Bank A: the console will not start until its operation field is filled. OPERATION FIELD: [ _ _ _ _ _ _ ]. The field takes the six-letter name of the operation row 17 defines.","visualType":"meta","whatTheySee":"A six-letter operation field, unlit, on the flood console.","taskPrompt":"Submit the six-letter name of the operation row 17 defines.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The pivot card that selects the manual row, the printed row 17 with its job and mask, and the unlit operation field.","operatorTaskDescription":"The Observer records the manual page; the Analyst applies the Stage 2 pivot to select row 17 and reads its job and mask; the Operator fills the operation field.","requiredDiscoveries":{"observerDiscovery":"Records the console manual and notes row 17 prints a job and a six-letter class mask.","analystDiscovery":"Uses pivot 17 to select the row and derives the six-letter F-name from job plus mask."}},"coordinationChain":{"observerProduces":"Observer reports the numbered manual page beside the noise wall.","analystTransforms":"Analyst applies the pivot card and isolates row 17: the gate operation, class F******.","operatorExecutes":"Operator submits the six-letter operation name, unlocking P26."},"hints":["The flood is not meant to be read; the manual beside it is, and an earlier recovery tells you which row of it matters: the Stage 2 pivot subject heading, 17.","Row 17 prints the job - keeping only the lines that pass the test - and a class mask: F******, six letters, first letter F.","The gate runs that operation on the stream; give the field the six-letter verb that names the job row 17 describes."],"narrativeObjective":"Cut the flood with the manual instead of reading it: select the one row that names the gate operation.","roleDependencyLevel":"D4"}',
  answer_metadata = '{"acceptedAnswer":"FILTER","validationMethod":"exact","fullSolution":"The Stage 2 pivot card selects manual row 17, which defines the gate operation - keep only the lines that pass the pivot test, discard the rest - and prints the class mask F******. The six-letter verb that names that job is FILTER."}',
  metadata = '{"type":"EXTRACTION","difficulty":4.5,"time":"10m","storyReveal":"The flood console was never a test of endurance. It is the programme''s own method on display: Candidate 00 tried to hold all of it at once in 2021 and broke, while the console demonstrates that one line, selected by the pivot, empties the noise. The house teaches its operators to cut, not to consume.","locationClue":{"format":"Research-Note","clueText":"LINA''S NOTE: \"Ascend to the holographic optics lab on the 1st floor.\"","solution":"Holographic Prototyping Lab","nextPhysicalLocation":"[ENGINEERING BLOCK] - Holographic Lab","nextQrNode":"QR-NODE-26","explanation":"Points to the holographic optics lab."},"evidenceUnlocked":{"id":"EVID-P25","category":"Lab Note","title":"Lab Notebook Fragment #64","state":"RECOVERED","timestamp":"Stage 4","source":"Server rack cooling fan assembly","content":"In 2021, Candidate 00 tried to ingest all two thousand bytes at once. His mental stack overflowed. Three people sifting the noise, each holding only a fraction, never break: the pivot does the cutting."},"whyTeamworkMatters":"Only the observer sees the manual page; only the analyst holds the pivot that selects the row; only the operator can run the operation the row defines.","feeds":"P24"}'
WHERE code = 'P25';

-- P26 The Mirror II - Stage 4
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Systems Architecture Lab - Three Phone Shards","dataPayload":"THREE PHONE SHARDS on the architecture lab bench, each mounted at a different angle facing a polished steel plate. LEFT SHARD carries R-E-F-L with a small arrow pointing across to the next mount. CENTER SHARD carries E-C-T. RIGHT SHARD carries I-O-N with an arrow pointing away from the plate. The bench plate is a plane mirror; the mount card says the shards were arranged so that a beam crossing the bench picks them up in order and the plate turns the last one back at the reader.","visualType":"observation","whatTheySee":"Three phone-mounted shards around a plane mirror, each carrying a fragment of letters; two arrows show the crossing direction.","taskPrompt":"Record each shard exactly as mounted, and record the direction each arrow points.","intermediateOutput":"Three shard fragments in mount order, with a crossing arrow on the first and a return arrow on the last."},"analyst":{"role":"ANALYST","screenTitle":"Bench Diagram - Read Order","dataPayload":"BENCH DIAGRAM, analyst overlay: the mount card is explicit that the shards are not three words but one line of reading cut into three pieces. The crossing arrow on the left shard starts the line; the return arrow on the right shard marks the plate, which is a plane mirror and turns the beam back toward whoever is reading the bench. A plane mirror does one thing to a beam - it sends it back the way it came - and the lab names that effect. The three fragments sit in reading order along that beam; the name of what the plate does to a beam is ten letters.","visualType":"document-forensics","whatTheySee":"A diagram marking where the beam starts, where it turns, and where it returns, with the three fragments placed along it.","taskPrompt":"Use the beam direction to fix the reading order of the fragments, then name what the plate does to a beam.","intermediateOutput":"Reading order is fixed by the beam; the plate''s effect is the lab''s question and is ten letters long."},"operator":{"role":"OPERATOR","screenTitle":"Architecture Lab Terminal - Turned Beam Field","dataPayload":"ARCHITECTURE LAB TERMINAL: the bench will not power down until the terminal is given the effect this bench exists to demonstrate. FIELD: [ _ _ _ _ _ _ _ _ _ _ ] - a plane mirror does THIS to a beam, ten letters. The three shard fragments are printed above the field in mount order.","visualType":"terminal","whatTheySee":"A ten-letter field on the lab terminal, with the three shard fragments printed above it in mount order.","taskPrompt":"Submit the ten-letter name of the effect the bench demonstrates.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The lab terminal with a ten-letter field, the three shard fragments printed in mount order above it, and the plane mirror on the bench itself.","operatorTaskDescription":"The Observer records the shards and the arrow directions; the Analyst fixes the reading order from the beam diagram; the Operator gives the terminal the effect the bench demonstrates.","requiredDiscoveries":{"observerDiscovery":"Records the three shard fragments and both arrows exactly as mounted.","analystDiscovery":"Reads the bench diagram to fix reading order and identifies that the plate turns a beam back on itself."}},"coordinationChain":{"observerProduces":"Observer reports the three shard fragments and the arrow directions on the bench.","analystTransforms":"Analyst fixes the beam read order and identifies what the plate does to the beam.","operatorExecutes":"Operator submits the ten-letter effect name, unlocking P27."},"hints":["The three shards are not three short words; the mount card says the line was cut. Put them in the order the arrows cross the bench before you read anything.","The left arrow starts the beam moving across the mounts; the right arrow points off the plate. A plane mirror sends a beam back the way it came - what does the lab call that?","Assemble the fragments in crossing order and count the letters: the lab names the returned-beam effect, and the terminal wants exactly that word."],"narrativeObjective":"Reconstruct one line of reading from three shards by following the beam the plane mirror turns back.","roleDependencyLevel":"D4"}',
  answer_metadata = '{"acceptedAnswer":"REFLECTION","validationMethod":"case_insensitive","fullSolution":"The three phone shards carry R-E-F-L, E-C-T and I-O-N; the arrows mount them in crossing order along the bench beam, and the plane mirror on the bench turns the last fragment back toward the reader. Assemble in beam order: R-E-F-L / E-C-T / I-O-N = REFLECTION. The bench exists to demonstrate what a plane mirror does to a beam."}',
  metadata = '{"type":"THREE_PHONE","difficulty":4.5,"time":"12m","storyReveal":"The hologram activates: the true echo is not on glass. Three fragments only become a word when the beam - and the team - cross the same bench in order.","locationClue":{"format":"Poetic","clueText":"LINA''S NOTE: \"Ascend to the systems architecture lab. Whiteboards map dependency trees.\"","solution":"Computer Systems Architecture Lab","nextPhysicalLocation":"[ENGINEERING BLOCK] - Architecture Lab","nextQrNode":"QR-NODE-27","explanation":"Points to the architecture lab."},"evidenceUnlocked":{"id":"EVID-P26","category":"Audio","title":"Dictaphone Memo REC-18: Coherence","state":"RECOVERED","timestamp":"Stage 4","source":"Optical bench laser casing","content":"The syndicate is in the courtyard, searching for a flash drive. The bench showed me the truth: you cannot steal what does not exist in any single place. Coherence only appears when the pieces are read in order."},"whyTeamworkMatters":"Only the observer sees the mounted shards and arrows; only the analyst holds the bench diagram that fixes reading order; only the operator can give the terminal the effect name. No single role can read the line alone.","feeds":"P25"}'
WHERE code = 'P26';

-- P27 The Dependency - Stage 4
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Research Chamber - Dependency Graph Viewer","dataPayload":"DEPENDENCY GRAPH, nine nodes in one directed chain across the research chamber whiteboard: S, then T, then R, then U, then C, then T, then U, then R, then E - each arrow points forward, root left, leaf right. A stained note pinned beneath the graph reads: THE ROOT AND THE LEAF ARE THE SAME PERSON. A second note, in the archivist hand, reads: NINE NODES, ONE DEPENDENCY, ONE WORD.","visualType":"chart","whatTheySee":"A nine-node directed chain on the whiteboard, with two pinned notes, one of them naming the dependency as a person.","taskPrompt":"Trace the chain arrow by arrow from root to leaf and record the nodes in order.","intermediateOutput":"Nine nodes, one directed chain, root on the left and leaf on the right."},"analyst":{"role":"ANALYST","screenTitle":"Topological Sort Verifier","dataPayload":"SORT VERIFIER: the chain is valid - root has in-degree zero, leaf has out-degree zero, every edge points forward, and the sort is unique. The verifier also holds the chamber card: a rooted dependency where the root and the leaf are the same person is what the programme calls its own arrangement of dependents, and the institution will not print its name in the open. The graph is the definition of that arrangement, drawn out. Nine nodes, and the label for what a graph of dependencies is.","visualType":"document-forensics","whatTheySee":"A verifier confirming the chain sorts uniquely, beside the chamber card that refuses to name the arrangement outright.","taskPrompt":"Confirm the sorted chain, then name what a rooted graph of dependencies is; the label is nine letters.","intermediateOutput":"Chain confirmed and unique; the label for a rooted dependency arrangement is nine letters and is not printed plainly."},"operator":{"role":"OPERATOR","screenTitle":"Architecture Compiler - Foundation Field","dataPayload":"ARCHITECTURE COMPILER: FOUNDATION: [ _ _ _ _ _ _ _ _ _ ]. The graph and both notes are reproduced on the compiler screen in reading order. The field wants the nine-letter name of the arrangement the graph draws.","visualType":"terminal","whatTheySee":"A nine-letter foundation field on the compiler, with the graph and notes above it.","taskPrompt":"Submit the nine-letter name of the arrangement.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The architecture compiler with its nine-letter foundation field, the reproduced graph, and the two notes from the research chamber board.","operatorTaskDescription":"The Observer traces the nine-node chain from the whiteboard; the Analyst verifies the unique sort and reads the chamber card; the Operator submits the nine-letter label for the arrangement the graph draws.","requiredDiscoveries":{"observerDiscovery":"Records the nine nodes in arrow order, root to leaf, and notes the pinned claim that root and leaf are the same person.","analystDiscovery":"Verifies the chain sorts uniquely and reads the chamber card: a rooted graph of dependencies has a nine-letter name."}},"coordinationChain":{"observerProduces":"Observer reports the nine nodes in arrow order and both pinned notes.","analystTransforms":"Analyst verifies the unique sort and identifies the nine-letter name for a rooted dependency arrangement.","operatorExecutes":"Operator submits the nine-letter label, unlocking P28."},"hints":["The graph is a chain, not a tree with branches: follow the arrows from the root on the left, one node at a time, to the leaf on the right.","One of the pinned notes says the root and the leaf are the same person. That makes this a rooted arrangement of dependents, and the chamber card refuses to print its name.","The compiler field wants the nine-letter word for a rooted arrangement of dependents - the thing the graph draws. Count the nodes: the label is the same length as the chain."],"narrativeObjective":"Trace the dependency chain to the nine-letter name of the arrangement the programme will not print.","roleDependencyLevel":"D4"}',
  answer_metadata = '{"acceptedAnswer":"STRUCTURE","validationMethod":"case_insensitive","fullSolution":"The whiteboard graph is a nine-node directed chain: S, T, R, U, C, T, U, R, E, arrows pointing forward, root on the left. The pin note says root and leaf are the same person, which makes it a rooted arrangement of dependents; the chamber card refuses to print that arrangement''s name. A rooted graph of dependencies is a STRUCTURE, nine letters."}',
  metadata = '{"type":"LOGIC","difficulty":4.5,"time":"11m","storyReveal":"The terminal answers: FOUNDATIONAL ARRANGEMENT COMPILED. The programme hangs its whole arrangement on one person who is both where its dependencies begin and where they end.","locationClue":{"format":"Research-Note","clueText":"LINA''S NOTE: \"Enter the cyber-physical research chamber. The fragment cylinder glows on its pedestal.\"","solution":"Cyber-Physical Research Chamber","nextPhysicalLocation":"[ENGINEERING BLOCK] - Research Chamber","nextQrNode":"QR-NODE-28","explanation":"Points to the research chamber."},"evidenceUnlocked":{"id":"EVID-P27","category":"Lab Note","title":"Lab Notebook Fragment #72","state":"RECOVERED","timestamp":"Stage 4","source":"Systems lab server terminal","content":"The chamber card will not print the arrangement''s name, but it does print the shape: root and leaf are one person. The graph is nine nodes long and the label is nine letters long. The next cylinder is not a symbol - it is a piece of a mind."},"whyTeamworkMatters":"Only the observer can trace the chain from the whiteboard; only the analyst can verify the sort and read the chamber card; only the operator can enter the nine-letter label.","feeds":"P26"}'
